import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { parseLeadMagnetPostbackPayload } from "./types.ts";
import type { LeadMagnetPostbackTriggerInput, LeadMagnetPostbackHandleResult } from "./types.ts";
import { handleFollowConfirmPostback, resendFrameworkOfferDm, resendLeadMagnetDeliveryDm, sendDeliveryMessage } from "./followGateRuntime.ts";
import type { LeadMagnetCampaignRow, LeadMagnetEnrollmentRow } from "./types.ts";

type EnrollmentWithCampaign = LeadMagnetEnrollmentRow & {
  campaign: LeadMagnetCampaignRow | LeadMagnetCampaignRow[] | null;
};

export async function handleLeadMagnetPostbackTrigger(
  admin: SupabaseClient,
  input: LeadMagnetPostbackTriggerInput,
): Promise<LeadMagnetPostbackHandleResult> {
  const parsed = parseLeadMagnetPostbackPayload(input.payload);
  if (!parsed) return { handled: false };

  const { data: enrollment, error } = await admin
    .from("lead_magnet_enrollments")
    .select("*, campaign:lead_magnet_campaigns(*)")
    .eq("id", parsed.enrollmentId)
    .eq("organization_id", input.organizationId)
    .maybeSingle();

  if (error || !enrollment) {
    console.warn("[lead-magnet] enrollment not found for postback", parsed.enrollmentId);
    return { handled: false };
  }

  const joined = enrollment as EnrollmentWithCampaign;
  const campaignRaw = joined.campaign;
  const campaignRow = Array.isArray(campaignRaw) ? campaignRaw[0] : campaignRaw;
  if (!campaignRow) return { handled: false };

  const row = joined as LeadMagnetEnrollmentRow;
  if (row.status === "paused" || row.status === "failed") {
    return { handled: true };
  }

  if (parsed.action === "follow_confirm") {
    if (row.status === "framework_offered" || row.status === "follow_validated") {
      await resendFrameworkOfferDm(admin, {
        enrollment: row,
        campaign: campaignRow,
        accessToken: input.accessToken,
        pageId: input.pageId,
      });
      return { handled: true, followConfirm: { outcome: "material_sent" } };
    }
    if (row.status === "delivered") {
      await resendLeadMagnetDeliveryDm(admin, {
        enrollment: row,
        campaign: campaignRow,
        accessToken: input.accessToken,
        pageId: input.pageId,
      });
      return { handled: true, followConfirm: { outcome: "material_sent" } };
    }

    const followConfirm = await handleFollowConfirmPostback(admin, {
      enrollment: row,
      campaign: campaignRow,
      accessToken: input.accessToken,
      pageId: input.pageId,
    });
    return { handled: true, followConfirm };
  }

  if (parsed.action === "get_framework") {
    if (row.status === "delivered") {
      return { handled: true };
    }
    await sendDeliveryMessage(admin, {
      enrollment: row,
      campaign: campaignRow,
      accessToken: input.accessToken,
      pageId: input.pageId,
    });
    return { handled: true };
  }

  return { handled: false };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import type { LeadMagnetPlatform } from "./types.ts";

function formatInstagramLabel(username: string | null | undefined, name: string | null | undefined): string {
  const user = (username ?? "").trim().replace(/^@/, "");
  if (user) return `@${user}`;
  const display = (name ?? "").trim();
  if (display) return display;
  return "";
}

async function resolveAccountIdForPlatform(
  admin: SupabaseClient,
  campaignId: string,
  platform: LeadMagnetPlatform,
  legacyAccountId: string | null | undefined,
): Promise<string> {
  const { data: row } = await admin
    .from("lead_magnet_campaign_accounts")
    .select("account_id")
    .eq("campaign_id", campaignId)
    .eq("platform", platform)
    .maybeSingle();

  const fromJoin = (row?.account_id ?? "").trim();
  if (fromJoin) return fromJoin;

  return (legacyAccountId ?? "").trim();
}

/** Connected social account label for leads.created_by_name (multi-tenant). */
export async function resolveLeadMagnetAccountLabel(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    campaignId: string;
    platform: LeadMagnetPlatform;
    legacyAccountId?: string | null;
  },
): Promise<string> {
  const accountId = await resolveAccountIdForPlatform(
    admin,
    args.campaignId,
    args.platform,
    args.legacyAccountId,
  );

  if (!accountId) {
    return args.platform === "instagram" ? "Instagram" : "Facebook Page";
  }

  if (args.platform === "instagram") {
    const { data: ig } = await admin
      .from("organization_instagram_accounts")
      .select("instagram_username, instagram_name")
      .eq("organization_id", args.organizationId)
      .eq("instagram_business_account_id", accountId)
      .eq("is_active", true)
      .order("updated_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    const label = formatInstagramLabel(ig?.instagram_username, ig?.instagram_name);
    if (label) return label;
    return `IG ${accountId.slice(0, 8)}`;
  }

  const { data: fb } = await admin
    .from("organization_facebook_pages")
    .select("page_name")
    .eq("organization_id", args.organizationId)
    .eq("facebook_page_id", accountId)
    .eq("is_active", true)
    .order("updated_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  const pageName = (fb?.page_name ?? "").trim();
  if (pageName) return pageName;
  return `Page ${accountId.slice(0, 8)}`;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { handleLeadMagnetCommentTrigger } from "./commentTriggerHandler.ts";
import { handleLeadMagnetInboundMessage } from "./inbound/handleInboundMessage.ts";
import { handleLeadMagnetPostbackTrigger } from "./postbackHandler.ts";
import { resolveLeadMagnetEntitlement } from "./leadMagnetEntitlement.ts";
import type { LeadMagnetRuntimeInput } from "./types.ts";

export async function runLeadMagnetRuntime(
  admin: SupabaseClient,
  input: LeadMagnetRuntimeInput,
): Promise<boolean> {
  try {
    const entitlement = await resolveLeadMagnetEntitlement(admin, input.organizationId);
    if (!entitlement.entitled) {
      console.log("[lead-magnet] skip runtime — not entitled", input.organizationId, entitlement.reason);
      return false;
    }

    if (input.trigger === "comment") {
      return await handleLeadMagnetCommentTrigger(admin, input);
    }
    if (input.trigger === "inbound_message") {
      return await handleLeadMagnetInboundMessage(admin, input);
    }
    const result = await handleLeadMagnetPostbackTrigger(admin, input);
    return result.handled;
  } catch (err) {
    console.error("[lead-magnet] runtime error:", err);
    return false;
  }
}

export async function invokeLeadMagnetRuntime(
  input: LeadMagnetRuntimeInput,
): Promise<void> {
  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  if (!supabaseUrl || !serviceRoleKey) return;

  try {
    const res = await fetch(`${supabaseUrl}/functions/v1/lead-magnet-runtime`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${serviceRoleKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(input),
    });
    if (!res.ok) {
      const errText = await res.text().catch(() => "");
      console.error("[lead-magnet] runtime invoke failed:", res.status, errText);
    }
  } catch (err) {
    console.error("[lead-magnet] runtime invoke error:", err);
  }
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { buildLeadMagnetButtonsMetadata } from "./leadMagnetLivechatDisplay.ts";
import type { LeadMagnetFirstDmMethod, LeadMagnetPlatform } from "./types.ts";

const META_GRAPH_VERSION = "v21.0";

declare const EdgeRuntime: {
  waitUntil: (promise: Promise<unknown>) => void;
};

function deferDmPersistence(work: Promise<unknown>): void {
  if (typeof EdgeRuntime !== "undefined" && typeof EdgeRuntime.waitUntil === "function") {
    EdgeRuntime.waitUntil(work);
    return;
  }
  void work;
}

export type LeadMagnetSendResult = {
  ok: boolean;
  messageId?: string | null;
  conversationId?: string | null;
  recipientId?: string | null;
  error?: string;
  isSessionExpired?: boolean;
  firstDmMethod?: LeadMagnetFirstDmMethod;
  privateReplyEndpoint?: string;
  metaErrorCode?: number;
  metaErrorSubcode?: number;
};

type ButtonSpec =
  | { type: "postback"; title: string; payload: string }
  | { type: "web_url"; title: string; url: string };

type MetaSendResponse = {
  ok: boolean;
  messageId?: string;
  recipientId?: string;
  error?: string;
  isSessionExpired?: boolean;
  metaErrorCode?: number;
  metaErrorSubcode?: number;
};

async function postMetaMessage(
  pageId: string,
  accessToken: string,
  recipientId: string,
  message: Record<string, unknown>,
): Promise<MetaSendResponse> {
  const url = `https://graph.facebook.com/${META_GRAPH_VERSION}/${pageId}/messages`;
  const res = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      recipient: { id: recipientId },
      message,
    }),
  });
  const data = await res.json() as {
    message_id?: string;
    recipient_id?: string;
    error?: { message?: string; code?: number; error_subcode?: number };
  };
  if (!res.ok) {
    const code = data.error?.code;
    const sub = data.error?.error_subcode;
    const isSessionExpired = code === 10 || sub === 2018278 || sub === 2534022;
    return {
      ok: false,
      error: data.error?.message ?? `Meta API ${res.status}`,
      isSessionExpired,
      metaErrorCode: code,
      metaErrorSubcode: sub,
    };
  }
  return { ok: true, messageId: data.message_id ?? null, recipientId: data.recipient_id ?? null };
}

/** First DM after a comment must use comment_id so Meta delivers to Messenger inbox. */
async function postCommentPrivateReply(
  endpointId: string,
  accessToken: string,
  commentId: string,
  message: Record<string, unknown>,
): Promise<MetaSendResponse> {
  const url = `https://graph.facebook.com/${META_GRAPH_VERSION}/${endpointId}/messages`;
  const res = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      recipient: { comment_id: commentId },
      message,
    }),
  });
  const data = await res.json() as {
    message_id?: string;
    recipient_id?: string;
    error?: { message?: string; code?: number; error_subcode?: number };
  };
  if (!res.ok) {
    const code = data.error?.code;
    const sub = data.error?.error_subcode;
    const isSessionExpired = code === 10 || sub === 2018278 || sub === 2534022;
    console.warn("[lead-magnet] private reply failed:", {
      endpointId,
      commentId,
      code,
      sub,
      message: data.error?.message,
    });
    return {
      ok: false,
      error: data.error?.message ?? `Meta API ${res.status}`,
      isSessionExpired,
      metaErrorCode: code,
      metaErrorSubcode: sub,
    };
  }
  console.log("[lead-magnet] private reply sent:", {
    endpointId,
    commentId,
    messageId: data.message_id,
    recipientId: data.recipient_id,
  });
  return { ok: true, messageId: data.message_id ?? null, recipientId: data.recipient_id ?? null };
}

function buildButtonTemplate(text: string, buttons: ButtonSpec[]): Record<string, unknown> {
  const metaButtons = buttons.map((b) => {
    if (b.type === "postback") {
      return { type: "postback", title: b.title.slice(0, 20), payload: b.payload };
    }
    return { type: "web_url", title: b.title.slice(0, 20), url: b.url };
  });
  return {
    attachment: {
      type: "template",
      payload: {
        template_type: "button",
        text: text.slice(0, 640),
        buttons: metaButtons,
      },
    },
  };
}

function appendButtonsAsPlainText(text: string, buttons?: ButtonSpec[]): string {
  if (!buttons?.length) return text;
  const lines = buttons.map((b) => {
    if (b.type === "web_url") return `${b.title}: ${b.url}`;
    return `Balas "${b.title}" untuk lanjut`;
  });
  return `${text}\n\n${lines.join("\n")}`;
}

async function sendCommentPrivateReplyFirstContact(
  platform: LeadMagnetPlatform,
  pageId: string,
  accountId: string,
  accessToken: string,
  commentId: string,
  text: string,
  buttons?: ButtonSpec[],
): Promise<LeadMagnetSendResult> {
  const endpoints: Array<{ id: string; label: string }> = platform === "instagram"
    ? [{ id: pageId, label: "page" }, { id: accountId, label: "ig_business" }]
    : [{ id: pageId, label: "page" }];
  let lastError = "Private reply failed on all endpoints";
  let lastCode: number | undefined;
  let lastSub: number | undefined;
  let lastSessionExpired: boolean | undefined;

  for (const ep of endpoints) {
    if (buttons?.length) {
      const buttonMessage = buildButtonTemplate(text, buttons);
      const buttonResult = await postCommentPrivateReply(ep.id, accessToken, commentId, buttonMessage);
      if (buttonResult.ok) {
        return {
          ok: true,
          messageId: buttonResult.messageId,
          recipientId: buttonResult.recipientId,
          firstDmMethod: "private_reply_button",
          privateReplyEndpoint: ep.label,
        };
      }
      lastError = buttonResult.error ?? lastError;
      lastCode = buttonResult.metaErrorCode ?? lastCode;
      lastSub = buttonResult.metaErrorSubcode ?? lastSub;
      lastSessionExpired = buttonResult.isSessionExpired ?? lastSessionExpired;
    }

    const textMessage = { text: appendButtonsAsPlainText(text, buttons).slice(0, 2000) };
    const textResult = await postCommentPrivateReply(ep.id, accessToken, commentId, textMessage);
    if (textResult.ok) {
      return {
        ok: true,
        messageId: textResult.messageId,
        recipientId: textResult.recipientId,
        firstDmMethod: "private_reply_text",
        privateReplyEndpoint: ep.label,
      };
    }
    lastError = textResult.error ?? lastError;
    lastCode = textResult.metaErrorCode ?? lastCode;
    lastSub = textResult.metaErrorSubcode ?? lastSub;
    lastSessionExpired = textResult.isSessionExpired ?? lastSessionExpired;
  }

  return {
    ok: false,
    error: lastError,
    isSessionExpired: lastSessionExpired,
    metaErrorCode: lastCode,
    metaErrorSubcode: lastSub,
  };
}

async function upsertInstagramConversation(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    accountId: string;
    participantScopedId: string;
    participantUsername: string | null;
  },
): Promise<string | null> {
  const { data: existing } = await admin
    .from("instagram_conversations")
    .select("id")
    .eq("organization_id", args.organizationId)
    .eq("instagram_business_account_id", args.accountId)
    .or(`customer_ig_id.eq.${args.participantScopedId},customer_external_id.eq.${args.participantScopedId}`)
    .order("updated_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  if (existing?.id) return existing.id as string;

  const convId = crypto.randomUUID();
  const ticketId = "IG-" + convId.replace(/-/g, "").slice(0, 8).toUpperCase();
  const now = new Date().toISOString();
  const orgOrGlobal = `organization_id.eq.${args.organizationId},organization_id.is.null`;
  const { data: openSt } = await admin.from("lead_statuses").select("id").or(orgOrGlobal).eq("name", "Open").maybeSingle();

  const { data: inserted, error } = await admin
    .from("instagram_conversations")
    .insert({
      id: convId,
      organization_id: args.organizationId,
      instagram_business_account_id: args.accountId,
      customer_ig_id: args.participantScopedId,
      customer_external_id: args.participantScopedId,
      ...(args.participantUsername ? { customer_name: args.participantUsername } : {}),
      ticket_id: ticketId,
      lead_status_id: openSt?.id ?? null,
      last_message_at: now,
      last_message_direction: "outbound",
      updated_at: now,
    })
    .select("id")
    .single();

  if (error) {
    const { data: retried } = await admin
      .from("instagram_conversations")
      .select("id")
      .eq("organization_id", args.organizationId)
      .eq("instagram_business_account_id", args.accountId)
      .or(`customer_ig_id.eq.${args.participantScopedId},customer_external_id.eq.${args.participantScopedId}`)
      .limit(1)
      .maybeSingle();
    return (retried?.id as string | undefined) ?? null;
  }
  return (inserted?.id as string | undefined) ?? null;
}

async function upsertFacebookConversation(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    pageId: string;
    participantScopedId: string;
    participantUsername: string | null;
  },
): Promise<string | null> {
  const { data: existing } = await admin
    .from("facebook_conversations")
    .select("id")
    .eq("organization_id", args.organizationId)
    .eq("facebook_page_id", args.pageId)
    .eq("customer_psid", args.participantScopedId)
    .limit(1)
    .maybeSingle();

  if (existing?.id) return existing.id as string;

  const convId = crypto.randomUUID();
  const ticketId = "FB-" + convId.replace(/-/g, "").slice(0, 8).toUpperCase();
  const now = new Date().toISOString();
  const orgOrGlobal = `organization_id.eq.${args.organizationId},organization_id.is.null`;
  const { data: openSt } = await admin.from("lead_statuses").select("id").or(orgOrGlobal).eq("name", "Open").maybeSingle();

  const { data: inserted, error } = await admin
    .from("facebook_conversations")
    .insert({
      id: convId,
      organization_id: args.organizationId,
      facebook_page_id: args.pageId,
      customer_psid: args.participantScopedId,
      ...(args.participantUsername ? { customer_name: args.participantUsername } : {}),
      ticket_id: ticketId,
      lead_status_id: openSt?.id ?? null,
      last_message_at: now,
      last_message_direction: "outbound",
      updated_at: now,
    })
    .select("id")
    .single();

  if (error) {
    const { data: retried } = await admin
      .from("facebook_conversations")
      .select("id")
      .eq("organization_id", args.organizationId)
      .eq("facebook_page_id", args.pageId)
      .eq("customer_psid", args.participantScopedId)
      .limit(1)
