  | "comment_replied"
  | "follow_checked"
  | "follow_gate_sent"
  | "follow_validated"
  | "framework_offered"
  | "material_offer_skipped"
  | "awaiting_contact"
  | "contact_collected"
  | "delivered"
  | "delivered_whatsapp"
  | "delivered_email"
